from lib.get_reading_time import *

def test_reading_time_above_1_minute():
    assert get_reading_time("text_long.txt") == "This text will take around 5 minutes to read."

def test_reading_time_of_1_minute():
    assert get_reading_time("text_1_min.txt") == "This text will take around 1 minute to read."

def test_reading_time_less_than_1_minute():
    assert get_reading_time("text_short.txt") == "This text will take less than a minute to read."

def test_text_is_empty():
    assert get_reading_time("text_empty.txt") == "There is no text here to read."
    
def test_text_is_just_spaces():
    assert get_reading_time("text_just_spaces.txt") == "There is no text here to read."

def test_string_less_than_1_minute():
    assert get_reading_time("this is quite a short message") == "This text will take less than a minute to read."

def test_string_empty():
    assert get_reading_time("") == "There is no text here to read."

def test_string_just_spaces():
    assert get_reading_time("   ") == "There is no text here to read."

